+	line    string
+	queries map[string]string
+	current string
+}
+
+type stateFn func(*Scanner) stateFn
+
+func getTag(line string) string {
+	re := regexp.MustCompile("^\\s*--\\s*name:\\s*(\\S+)")
+	matches := re.FindStringSubmatch(line)
+	if matches == nil {
+		return ""
+	}
+	return matches[1]
