	line := strings.Trim(s.line, " \t")
	if len(line) == 0 {
		return
	}

	// Initialize the query in the map only when we have actual content
	current, exists := s.queries[s.current]
	if !exists {
		current = ""
	}

	if len(current) > 0 {
		current = current + "\n"
	}

	current = current + line
	s.queries[s.current] = current
