+func (s *Scanner) Run(io *bufio.Scanner) map[string]string {
+	s.queries = make(map[string]string)
+
+	for state := initialState; io.Scan(); {
+		s.line = io.Text()
+		state = state(s)
+	}
+
+	return s.queries
+}
